def numeric_typography(text):
    text=re.sub(r'(?<![\w])-(?=\d)', '−\u2060',str(text))
    return re.sub(r'([0-9,]+) × (10[⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+)','\\1\u00a0×\u00a0\\2',text)

def p(text='',style=None,single=False,center=False):
    q=D.add_paragraph(numeric_typography(text),style)
    q.alignment=WD_ALIGN_PARAGRAPH.CENTER if center else WD_ALIGN_PARAGRAPH.JUSTIFY
    if single:q.paragraph_format.line_spacing=1
    return q
def heading(text,sub=False):
    q=p(text,'Heading 2' if sub else 'Heading 1');q.alignment=WD_ALIGN_PARAGRAPH.LEFT
    q.paragraph_format.space_before=Pt(8);q.paragraph_format.space_after=Pt(2)
    return q
