def link(q,label,url):
    h=OxmlElement('w:hyperlink');h.set(qn('r:id'),q.part.relate_to(url,RT.HYPERLINK,is_external=True))
    r=OxmlElement('w:r');props=OxmlElement('w:rPr')
    color=OxmlElement('w:color');color.set(qn('w:val'),'000000');props.append(color)
    fonts=OxmlElement('w:rFonts');fonts.set(qn('w:ascii'),'Times New Roman');fonts.set(qn('w:hAnsi'),'Times New Roman');props.append(fonts)
    r.append(props);t=OxmlElement('w:t');t.text=label;r.append(t);h.append(r);q._p.append(h)
def table(caption,headers,rows,widths):
    q=p(caption,single=True);q.paragraph_format.keep_with_next=True;q.paragraph_format.space_before=Pt(6)
    t=D.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    borders=OxmlElement('w:tblBorders')
    for n in ['top','left','bottom','right','insideH','insideV']:
        b=OxmlElement('w:'+n);b.set(qn('w:val'),'single');b.set(qn('w:sz'),'4');b.set(qn('w:color'),'D9D9D9');borders.append(b)
    t._tbl.tblPr.append(borders)
    margin=OxmlElement('w:tblCellMar')
    for n in ['top','bottom','left','right']:
        b=OxmlElement('w:'+n);b.set(qn('w:w'),'85');b.set(qn('w:type'),'dxa');margin.append(b)
    t._tbl.tblPr.append(margin)
    repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in [headers]+rows:
        cells=t.rows[0].cells if row is headers else t.add_row().cells
        for j,(c,text) in enumerate(zip(cells,row)):
            c.width=Cm(widths[j]);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            q=c.paragraphs[0];q.text=numeric_typography(text);q.paragraph_format.line_spacing=1
            q.paragraph_format.space_after=Pt(0);q.paragraph_format.keep_with_next=False
            q.alignment=WD_ALIGN_PARAGRAPH.LEFT if j==0 else WD_ALIGN_PARAGRAPH.CENTER
            if row is headers:
                sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'EDEDED');c._tc.get_or_add_tcPr().append(sh)
                for r in q.runs:r.bold=True
        cant=OxmlElement('w:cantSplit');cells[0]._tc.getparent().get_or_add_trPr().append(cant)
    p('').paragraph_format.line_spacing=1
    return t
